files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  min-width: 850px;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
}

.header {
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 40px;
  background-color: #fd24af;
}

.logo-link {
  width: 200px;
}

.header__menu-button {
  width: 40px;
  height: 40px;
  border: none;
  background-color: transparent;
  background-image: url(./images/hamburger-menu.svg);
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  cursor: pointer;
}

.header__menu-button:hover {
  opacity: 0.8;
}

.menu {
  position: absolute;
  bottom: 0;
  left: 0;
  display: none;
  width: 100%;
  border: 1px solid #000;
  border-top: 1px solid #000;
  padding: 40px;
  background-color: #fff;
  transform: translateY(100%);
}

.menu ul {
  display: flex;
  justify-content: center;
  font-size: 24px;
  list-style: none;
}

.menu a {
  border: 1px solid #000;
  padding: 10px 35px;
  color: #000;
  font-weight: 800;
  text-decoration: none;
  text-transform: uppercase;
  background-color: #ffc802;
}

.menu a:hover {
  text-decoration: underline;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  clip: rect(0 0 0 0);
  overflow: hidden;
}
